import Image from "next/image";
import { APP_NAME } from "@aps/shared";
import { cn } from "@/lib/utils";

/** Mark generated by `scripts/generate-brand-icons.mjs` (mascot head on orange squircle). */
const MARK_SRC = "/brand/mascot-mark.png";

type Props = {
  className?: string;
  size?: number;
  priority?: boolean;
  /** Show the product name (`APP_NAME`) beside the mark. */
  withWordmark?: boolean;
};

/** Product logo — mascot head peeking from an orange squircle. */
export function Logo({
  className,
  size = 32,
  priority = false,
  withWordmark = false,
}: Props) {
  const mark = (
    <Image
      src={MARK_SRC}
      alt={withWordmark ? "" : APP_NAME}
      width={size}
      height={size}
      priority={priority}
      className="shrink-0 rounded-[24%]"
    />
  );

  if (!withWordmark) {
    return <span className={cn("inline-flex", className)}>{mark}</span>;
  }

  return (
    <span
      className={cn(
        "inline-flex min-w-0 items-center gap-2 sm:gap-2.5",
        className,
      )}
    >
      {mark}
      <span className="font-display min-w-0 truncate whitespace-nowrap text-sm font-semibold tracking-tight">
        {APP_NAME}
      </span>
    </span>
  );
}
